import{_ as r,o as e,c as s,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-05-27:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-05-27:: Ceph Orchestration Meeting","date":"2019-05-27T00:00:00.000Z","updated":"2019-05-28T00:00:00.000Z","tags":["Ceph","Orchestration","Automation","Storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-27_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-05-27_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-05-27_-_-_Ceph_Orchestration_Meeting.md"};function i(a,t,l,p,g,_){return e(),s("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年3月28日</p><p><strong>会议主题</strong>： 讨论Ceph存储集群中的功能实现和改进方案。</p><p><strong>参会人员</strong>： Travis, Eric Fox, Stefan等人。</p><p><strong>会议内容</strong>：</p><p><strong>1. 会议取消情况</strong>：</p><ul><li>由于美国阵亡将士纪念日，美国团队成员无法参加，故Travis取消了本次会议。</li></ul><p><strong>2. Ceph相关议题</strong>：</p><ul><li><strong>Podcast评论</strong>： Travis更新了关于Ceph的播客，讨论了评论提交的问题。</li><li><strong>Trivial Completions</strong>： 讨论了新计划，并指出忽略属性可能带来的风险，建议返回失败以防止问题发生。</li><li><strong>Kiche信息持久化</strong>： 讨论了Kiche信息的持久化问题，提出了使用持久存储字典存储主机列表的方案。</li><li><strong>SSH Orchestrator</strong>： 讨论了SSH Orchestrator的实现，指出其存储已知主机列表的方式与其他Orchestrator不同，讨论了是否需要替换持久化存储字典以提高性能。</li><li><strong>Ansible Orchestrator</strong>： 讨论了Ansible Orchestrator的性能问题，提出了将部分信息缓存到Ansible中的方案，并讨论了是否需要修改playbook以实现快速版本。</li></ul><p><strong>3. 其他议题</strong>：</p><ul><li><strong>Ansible Orchestrator支持安全Ansible</strong>： 讨论了Ansible Orchestrator是否支持安全Ansible，指出这是当前工作的重点。</li><li><strong>测试自动化</strong>： 讨论了测试自动化的重要性，并指出应该优先考虑自动化测试。</li></ul><p><strong>4. 行动计划</strong>：</p><ul><li>完成Ansible Orchestrator的修改，并确保功能正常。</li><li>对Ceph进行自动化测试。</li><li>在下周的会议上继续讨论其他议题。</li></ul><p><strong>5. 会议总结</strong>： 本次会议讨论了Ceph存储集群中的功能实现和改进方案，并制定了相应的行动计划，强调了Ansible Orchestrator的重要性和测试自动化的重要性。</p>',14)])])}const d=r(n,[["render",i]]);export{c as __pageData,d as default};
